package com.kongye.floatball;

import android.app.Activity;
import android.content.Intent;
import android.graphics.drawable.AnimatedImageDrawable;
import android.media.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;

/** Debug variant only. Test results are numbers and flags, never image/audio exports. */
public class DiagnosticActivity extends Activity {
    private AudioTrack tone;private LinearLayout root;private TextView status;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);Prefs.of(this).edit().putInt("qa_scroll_y",0).apply();build();handle(getIntent());}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handle(intent);}
    private void handle(Intent intent){if("qa_v24".equals(intent.getStringExtra("feature"))){V24Checks.run(this);return;}if("qa_v24_fixture".equals(intent.getStringExtra("feature"))){try{V24Checks.fixture(this);}catch(Exception e){Prefs.of(this).edit().putString("qa_v24_error",e.toString()).apply();}return;}if("qa_v23".equals(intent.getStringExtra("feature"))){V23Checks.run(this);return;}if("qa_v20".equals(intent.getStringExtra("feature"))){new Handler(Looper.getMainLooper()).postDelayed(()->V20Checks.run(this),300);return;}if("qa_browser_page".equals(intent.getStringExtra("feature"))){V20Checks.installPage(this);return;}if("qa_browser_state".equals(intent.getStringExtra("feature"))){V20Checks.inspectPage(this);return;}if("qa_browser_scroll".equals(intent.getStringExtra("feature"))){V20Checks.scrollPage();return;}if("qa_v19".equals(intent.getStringExtra("feature"))){new Handler(Looper.getMainLooper()).postDelayed(()->V19Checks.run(this),300);return;}if("qa_drop_ball".equals(intent.getStringExtra("feature"))){V19Checks.dropWindow();return;}if("qa_show_last_record_task".equals(intent.getStringExtra("feature"))){startActivity(new Intent(this,RecordingResultActivity.class).putExtra("path",Prefs.of(this).getString("last_record_uri","")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));return;}if("qa_sample_times".equals(intent.getStringExtra("feature"))){RecordingTimelineChecks.run(this);return;}if("qa_v18".equals(intent.getStringExtra("feature"))){new Handler(Looper.getMainLooper()).postDelayed(()->V18Checks.run(this),300);return;}String action=intent.getStringExtra("feature");if("qa_show_last_record".equals(action)){startActivity(new Intent(this,RecordingResultActivity.class).putExtra("path",Prefs.of(this).getString("last_record_uri","")));return;}if("qa_rules_self".equals(action)){startActivity(new Intent(this,AppBehaviorActivity.class).putExtra("query",getPackageName()));return;}if("qa_app_rules".equals(action)){startActivity(new Intent(this,AppBehaviorActivity.class).putExtra("query","com.android.settings"));return;}if("qa_record_pattern".equals(action)){pattern();return;}if("qa_record_video".equals(action)||"qa_record_video_tone".equals(action)||"qa_record_gif".equals(action)){pattern();if(action.equals("qa_record_video_tone")){tone();if(tone!=null)tone.setVolume(.05f);}new Handler(Looper.getMainLooper()).postDelayed(()->startForegroundService(new Intent(this,FloatService.class).putExtra("action",action.equals("qa_record_gif")?"gif_record":"record")),700);return;}if("qa_inspect_record".equals(action)){inspectVideo();inspectFrame();return;}if("qa_record_tone".equals(action)){tone();return;}if("qa_record_tools".equals(action)){new Handler(Looper.getMainLooper()).postDelayed(()->RecordingChecks.run(this),300);return;}if("qa_app_picker".equals(action)){startActivity(new Intent(this,AppPickerActivity.class).putExtra("query","com.kongye.floatball"));return;}if("qa_edit_tools".equals(action)){new Handler(Looper.getMainLooper()).postDelayed(()->EditorChecks.run(this),300);return;}if(action!=null)new Handler(Looper.getMainLooper()).postDelayed(()->startForegroundService(new Intent(this,FloatService.class).putExtra("action",action)),700);}
    private void build(){ThemePolicy.apply(this);root=Ui.column(this);root.setBackgroundColor(Ui.BG);Ui.pad(root,18,36,18,18);root.addView(Ui.text(this,"空叶本地功能验收",22,Ui.INK,true));status=Ui.text(this,"仅显示生成的测试内容，不导出画面或音频。",12,Ui.MUTED,false);root.addView(status);Ui.gap(root,10);
        LinearLayout buttons=Ui.row(this);buttons.addView(Ui.button(this,"测试音开关",true,this::tone));buttons.addView(Ui.button(this,"检查录屏",false,this::inspectVideo));buttons.addView(Ui.button(this,"检查图像",false,this::inspectArt));root.addView(buttons);Ui.gap(root,12);
        ScrollView scroll=new ScrollView(this);LinearLayout body=Ui.column(this);for(int i=0;i<80;i++){LinearLayout card=Ui.card(this);card.setBackground(Ui.bg(i%2==0?Ui.PALE:Ui.SURFACE,12,this));card.addView(Ui.text(this,String.format(java.util.Locale.US,"KONGYE TEST ROW %02d",i),18,Ui.INK,true));Ui.gap(card,8);card.addView(Ui.text(this,"这是程序生成的滚动拼接测试内容。\nABCDEFGHIJKLMNOP 0123456789\n每一行都有不同编号，以便验证拼接。",13,Ui.MUTED,false));body.addView(card);Ui.gap(body,8);}scroll.setOnScrollChangeListener((view,x,y,oldX,oldY)->Prefs.of(this).edit().putInt("qa_scroll_y",y).apply());scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(Ui.dp(this,18),insets.getSystemWindowInsetTop()+Ui.dp(this,24),Ui.dp(this,18),insets.getSystemWindowInsetBottom()+Ui.dp(this,12));return insets.consumeSystemWindowInsets();});}
    private void pattern(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);View pattern=new View(this){final android.graphics.Paint p=new android.graphics.Paint();protected void onDraw(android.graphics.Canvas c){int[] colors={android.graphics.Color.RED,android.graphics.Color.GREEN,android.graphics.Color.BLUE,android.graphics.Color.YELLOW};for(int i=0;i<4;i++){p.setColor(colors[i]);float x=(i%2)*getWidth()/2f,y=(i/2)*getHeight()/2f;c.drawRect(x,y,x+getWidth()/2f,y+getHeight()/2f,p);}int[] at=new int[2];getLocationOnScreen(at);Prefs.of(DiagnosticActivity.this).edit().putInt("qa_pattern_x",at[0]).putInt("qa_pattern_y",at[1]).putInt("qa_pattern_w",getWidth()).putInt("qa_pattern_h",getHeight()).apply();}};pattern.setContentDescription("程序生成的录制颜色测试画面");setContentView(pattern);}
    private void inspectFrame(){new Thread(()->{android.media.MediaMetadataRetriever r=new android.media.MediaMetadataRetriever();android.graphics.Bitmap b=null;String error="";try{r.setDataSource(Prefs.of(this).getString("last_record_uri",""));b=r.getFrameAtTime(300000,android.media.MediaMetadataRetriever.OPTION_CLOSEST);if(b==null)throw new java.io.IOException("Missing frame");android.content.SharedPreferences.Editor e=Prefs.of(this).edit();for(int i=0;i<4;i++)e.putInt("qa_record_pixel_"+i,b.getPixel(Math.min(b.getWidth()-1,(i%2==0?1:3)*b.getWidth()/4),Math.min(b.getHeight()-1,(i<2?1:3)*b.getHeight()/4)));int white=0;for(int yy=b.getHeight()*3/4;yy<b.getHeight();yy++)for(int xx=b.getWidth()/2;xx<b.getWidth();xx++){int pixel=b.getPixel(xx,yy);if(android.graphics.Color.red(pixel)>210&&android.graphics.Color.green(pixel)>210&&android.graphics.Color.blue(pixel)>210)white++;}e.putInt("qa_record_watermark_white",white);e.putInt("qa_record_frame_w",b.getWidth()).putInt("qa_record_frame_h",b.getHeight()).apply();}catch(Exception ex){error=ex.toString();}finally{if(b!=null)b.recycle();try{r.release();}catch(Exception ignored){}Prefs.of(this).edit().putString("qa_record_frame_error",error).apply();}},"Kongye-FrameCheck").start();}
    private void tone(){if(tone!=null){tone.release();tone=null;status.setText("测试音已停止");return;}int rate=44100;short[] pcm=new short[rate];for(int i=0;i<pcm.length;i++)pcm[i]=(short)(10000*Math.sin(2*Math.PI*440*i/rate));AudioAttributes.Builder attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC);if(Build.VERSION.SDK_INT>=29)attributes.setAllowedCapturePolicy(AudioAttributes.ALLOW_CAPTURE_BY_ALL);tone=new AudioTrack.Builder().setAudioAttributes(attributes.build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(rate).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build()).setTransferMode(AudioTrack.MODE_STATIC).setBufferSizeInBytes(pcm.length*2).build();tone.write(pcm,0,pcm.length);tone.setLoopPoints(0,pcm.length,-1);tone.play();status.setText("440 Hz 程序测试音播放中；再次点击停止");}
    private void inspectArt(){View art=BallArt.create(this,Ui.dp(this,48));boolean animated=false;if(art instanceof ImageView image&&Build.VERSION.SDK_INT>=28)animated=image.getDrawable() instanceof AnimatedImageDrawable;Prefs.of(this).edit().putBoolean("qa_art_loaded",art!=null).putBoolean("qa_art_animated",animated).putBoolean("qa_dark",ThemePolicy.isDark(this)).apply();status.setText("自定义图片已解码："+(art!=null)+"；GIF 动画："+animated+"；深色："+Ui.dark);}
    private void inspectVideo(){new Thread(()->{MediaExtractor extractor=new MediaExtractor();int audioIndex=-1,videoIndex=-1;long duration=0,audioDuration=0,videoDuration=0;int width=0,height=0,peak=0;String error="";try{String location=Prefs.of(this).getString("last_record_uri","");if(location.startsWith("content:"))extractor.setDataSource(this,Uri.parse(location),null);else extractor.setDataSource(location);for(int i=0;i<extractor.getTrackCount();i++){MediaFormat f=extractor.getTrackFormat(i);String mime=f.getString(MediaFormat.KEY_MIME);if(mime.startsWith("video/")){videoIndex=i;width=f.getInteger(MediaFormat.KEY_WIDTH);height=f.getInteger(MediaFormat.KEY_HEIGHT);if(f.containsKey(MediaFormat.KEY_DURATION))videoDuration=f.getLong(MediaFormat.KEY_DURATION);}if(mime.startsWith("audio/")){audioIndex=i;if(f.containsKey(MediaFormat.KEY_DURATION))audioDuration=f.getLong(MediaFormat.KEY_DURATION);}if(f.containsKey(MediaFormat.KEY_DURATION))duration=Math.max(duration,f.getLong(MediaFormat.KEY_DURATION));}if(audioIndex>=0)peak=decodePeak(extractor,audioIndex);}
        catch(Exception e){error=e.toString();}finally{extractor.release();}Prefs.of(this).edit().putBoolean("qa_video",videoIndex>=0).putBoolean("qa_audio",audioIndex>=0).putLong("qa_duration_us",duration).putLong("qa_audio_duration_us",audioDuration).putLong("qa_video_duration_us",videoDuration).putInt("qa_video_width",width).putInt("qa_video_height",height).putInt("qa_audio_peak",peak).putString("qa_error",error).apply();final String text="视频轨："+(videoIndex>=0)+"；音轨："+(audioIndex>=0)+"；时长(ms)："+duration/1000+"；音频峰值："+peak+" "+error;runOnUiThread(()->status.setText(text));},"Kongye-Inspect").start();}
    private int decodePeak(MediaExtractor extractor,int track)throws Exception{extractor.selectTrack(track);MediaFormat format=extractor.getTrackFormat(track);MediaCodec codec=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));int peak=0;try{codec.configure(format,null,null,0);codec.start();boolean inputEnd=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long until=SystemClock.elapsedRealtime()+5000;while(SystemClock.elapsedRealtime()<until){if(!inputEnd){int in=codec.dequeueInputBuffer(1000);if(in>=0){java.nio.ByteBuffer b=codec.getInputBuffer(in);int count=extractor.readSampleData(b,0);if(count<0){codec.queueInputBuffer(in,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnd=true;}else{codec.queueInputBuffer(in,0,count,extractor.getSampleTime(),0);extractor.advance();}}}int out=codec.dequeueOutputBuffer(info,1000);if(out>=0){java.nio.ByteBuffer b=codec.getOutputBuffer(out);b.order(java.nio.ByteOrder.LITTLE_ENDIAN);b.position(info.offset);b.limit(info.offset+info.size);while(b.remaining()>=2)peak=Math.max(peak,Math.abs((int)b.getShort()));codec.releaseOutputBuffer(out,false);if(info.presentationTimeUs>2000000||(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0)break;}}}finally{try{codec.stop();}catch(Exception ignored){}codec.release();}return peak;}
    @Override public void onDestroy(){if(tone!=null){tone.release();tone=null;}super.onDestroy();}
}
